INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000001','e784bdd3-43aa-4c2a-a61f-32bd4b93192b','Una muestra reviste la superficie interna de una cavidad. ¿Qué tejido cumple principalmente esta función?','El tejido epitelial cubre superficies y reviste cavidades.','[{"text":"Epitelial","correct":true},{"text":"Muscular","correct":false},{"text":"Nervioso","correct":false},{"text":"Conectivo exclusivamente","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues',1001,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000002','e784bdd3-43aa-4c2a-a61f-32bd4b93192b','¿Qué característica orienta hacia tejido conectivo?','El tejido conectivo une y sostiene, y su matriz extracelular es un componente importante.','[{"text":"La ausencia obligatoria de matriz","correct":false},{"text":"La contracción como única función","correct":false},{"text":"La transmisión exclusiva de impulsos nerviosos","correct":false},{"text":"Una matriz extracelular que participa en el soporte","correct":true}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues',1002,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
