INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000007','e784bdd3-43aa-4c2a-a61f-32bd4b93192b','¿Qué serosa se relaciona con los pulmones?','La pleura recubre los pulmones y reviste su cavidad; el pericardio corresponde al corazón.','[{"text":"Pericardio","correct":false},{"text":"Membrana sinovial","correct":false},{"text":"Pleura","correct":true},{"text":"Peritoneo","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues',1007,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000008','e784bdd3-43aa-4c2a-a61f-32bd4b93192b','¿Cómo se clasifica una membrana sinovial?','Las membranas sinoviales pertenecen al grupo de membranas de tejido conectivo.','[{"text":"Capa germinal","correct":false},{"text":"Membrana de tejido conectivo","correct":true},{"text":"Epitelio de la epidermis","correct":false},{"text":"Membrana plasmática de una neurona","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues',1008,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000009','e784bdd3-43aa-4c2a-a61f-32bd4b93192b','¿De qué capa germinal deriva principalmente el tejido nervioso?','El tejido nervioso deriva principalmente del ectodermo.','[{"text":"Ectodermo","correct":true},{"text":"Endodermo exclusivamente","correct":false},{"text":"Mesodermo exclusivamente","correct":false},{"text":"Peritoneo","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues',1009,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000010','e784bdd3-43aa-4c2a-a61f-32bd4b93192b','En una pared visceral se observan epitelio, conectivo y músculo. ¿Qué interpretación es correcta?','Los tejidos se combinan en órganos y conservan funciones diferentes dentro de una misma estructura.','[{"text":"La muestra debe contener tres órganos distintos","correct":false},{"text":"Todos los componentes son epiteliales","correct":false},{"text":"La presencia de músculo excluye el epitelio","correct":false},{"text":"Un órgano puede integrar varios tejidos","correct":true}]'::jsonb,2,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues',1010,'clinical_case','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
UPDATE public.curriculum_lessons SET title='Fisiología I: membrana y transporte celular',summary='Comprende la permeabilidad selectiva y diferencia difusión, ósmosis y transporte activo.',content='### Objetivos de repaso
Explicar por qué una membrana selecciona qué sustancias la atraviesan y comparar los mecanismos básicos de transporte. Este bloque desarrolla la fisiología celular incluida en Fisiología I; no resume por sí solo toda la asignatura.

### Estructura de la membrana
La membrana plasmática delimita el interior celular. Está formada principalmente por una bicapa de fosfolípidos con proteínas y colesterol. Las cabezas hidrófilas se orientan hacia los medios acuosos; las colas hidrófobas quedan enfrentadas hacia el interior de la bicapa. La membrana es dinámica, no una pared rígida.

### Permeabilidad selectiva
Moléculas pequeñas no polares como oxígeno y dióxido de carbono pueden atravesar la bicapa. Los iones y muchas sustancias hidrosolubles requieren proteínas para cruzarla. Un canal crea una vía selectiva; un transportador se une a una sustancia y cambia de conformación. No todas las sustancias utilizan el mismo mecanismo.

### Transporte pasivo
No exige gasto directo de energía celular para impulsar el transporte. La difusión simple desplaza partículas a favor de su gradiente de concentración. La difusión facilitada también es pasiva, aunque utilice proteínas: «usa proteína» no significa «usa ATP».
La ósmosis es el movimiento neto de agua a través de una membrana selectivamente permeable. En condiciones comparables, el agua se desplaza hacia el lado con mayor concentración de solutos que no pueden atravesar la membrana.

### Transporte activo
Requiere energía y puede mover sustancias en contra de su gradiente. En el transporte activo primario la proteína utiliza ATP directamente. En el secundario, el movimiento de una sustancia aprovecha el gradiente de otra; la energía procede indirectamente de un gradiente mantenido por mecanismos activos.

### Aplicación razonada
Si un soluto cruza mediante una proteína a favor de su gradiente sin aporte energético directo, puede ser difusión facilitada. Para clasificar un transporte pregunta: ¿qué se mueve?, ¿en qué dirección respecto al gradiente?, ¿qué proteína interviene?, ¿de dónde procede la energía?

### Errores frecuentes
Ósmosis describe agua, no cualquier soluto. Difusión facilitada no es sinónimo de transporte activo. Un gradiente es una diferencia, no una estructura.

### Autoevaluación
Compara difusión simple, difusión facilitada y transporte activo con los criterios anteriores.

Material de entrenamiento original basado en fuentes; no es un examen oficial.',key_points='["Bicapa con cabezas hidrófilas y colas hidrófobas.","Difusión facilitada: proteína y transporte pasivo.","Ósmosis: movimiento neto de agua.","Transporte activo primario: uso directo de ATP.","Transporte activo secundario: acoplamiento a otro gradiente."]'::jsonb,source_files='[{"url":"https://www.uvic.cat/es/assignatura/4405","label":"UVic-UCC · Plan docente · alcance de la asignatura","verified_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane","label":"OpenStax · Texto académico abierto · fundamento del repaso","verified_at":"2026-10-30"}]'::jsonb,updated_at=now() WHERE id='21afcaf4-82c8-4ea6-8778-dd0ee108ec6b' AND (content='### En pocas palabras

Introduction aux bases moléculaires, cellulaires et aux fonctions des systèmes.

### Contenido esencial

Fisiología I introduce la estructura y el funcionamiento normal del cuerpo humano. La asignatura busca relacionar las bases moleculares y fisiológicas de células y tejidos con las funciones de los diferentes aparatos y sistemas, utilizando correctamente la terminología médica.

### Vocabulario y puntos clave

- bases moleculares y fisiológicas
- células y tejidos
- funciones de aparatos y sistemas
- terminología médica

### Para memorizar

Lee primero el contenido esencial, después repasa los términos clave y comprueba que puedes explicarlos sin mirar.

### Approfondissement
La fisiología estudia cómo funcionan normalmente las células, los tejidos y los sistemas. Comprender estos mecanismos permite interpretar después los cambios que aparecen con el ejercicio, la enfermedad o la lesión. En primer curso, es importante construir vínculos entre nivel celular, tejido y función global, utilizando una terminología médica precisa.' OR content='### Objetivos de repaso
Explicar por qué una membrana selecciona qué sustancias la atraviesan y comparar los mecanismos básicos de transporte. Este bloque desarrolla la fisiología celular incluida en Fisiología I; no resume por sí solo toda la asignatura.

### Estructura de la membrana
La membrana plasmática delimita el interior celular. Está formada principalmente por una bicapa de fosfolípidos con proteínas y colesterol. Las cabezas hidrófilas se orientan hacia los medios acuosos; las colas hidrófobas quedan enfrentadas hacia el interior de la bicapa. La membrana es dinámica, no una pared rígida.

### Permeabilidad selectiva
Moléculas pequeñas no polares como oxígeno y dióxido de carbono pueden atravesar la bicapa. Los iones y muchas sustancias hidrosolubles requieren proteínas para cruzarla. Un canal crea una vía selectiva; un transportador se une a una sustancia y cambia de conformación. No todas las sustancias utilizan el mismo mecanismo.

### Transporte pasivo
No exige gasto directo de energía celular para impulsar el transporte. La difusión simple desplaza partículas a favor de su gradiente de concentración. La difusión facilitada también es pasiva, aunque utilice proteínas: «usa proteína» no significa «usa ATP».
La ósmosis es el movimiento neto de agua a través de una membrana selectivamente permeable. En condiciones comparables, el agua se desplaza hacia el lado con mayor concentración de solutos que no pueden atravesar la membrana.

### Transporte activo
Requiere energía y puede mover sustancias en contra de su gradiente. En el transporte activo primario la proteína utiliza ATP directamente. En el secundario, el movimiento de una sustancia aprovecha el gradiente de otra; la energía procede indirectamente de un gradiente mantenido por mecanismos activos.

### Aplicación razonada
Si un soluto cruza mediante una proteína a favor de su gradiente sin aporte energético directo, puede ser difusión facilitada. Para clasificar un transporte pregunta: ¿qué se mueve?, ¿en qué dirección respecto al gradiente?, ¿qué proteína interviene?, ¿de dónde procede la energía?

### Errores frecuentes
Ósmosis describe agua, no cualquier soluto. Difusión facilitada no es sinónimo de transporte activo. Un gradiente es una diferencia, no una estructura.

### Autoevaluación
Compara difusión simple, difusión facilitada y transporte activo con los criterios anteriores.

Material de entrenamiento original basado en fuentes; no es un examen oficial.');
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000011','c2449f10-323d-4ba2-b438-fdc1f452dbf3','¿Hacia dónde se orientan las colas hidrófobas de los fosfolípidos en la bicapa?','Las colas hidrófobas se enfrentan en el interior; las cabezas contactan con el agua.','[{"text":"Hacia el interior de la bicapa","correct":true},{"text":"Hacia el líquido extracelular únicamente","correct":false},{"text":"Hacia el núcleo exclusivamente","correct":false},{"text":"Hacia el agua en ambas superficies","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane',1001,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000012','c2449f10-323d-4ba2-b438-fdc1f452dbf3','¿Qué molécula puede atravesar la bicapa por difusión simple con relativa facilidad?','El oxígeno es pequeño y no polar; los iones requieren vías proteicas para cruzar con facilidad.','[{"text":"Un ion sodio sin canal","correct":false},{"text":"Una proteína plasmática","correct":false},{"text":"Una molécula de ADN","correct":false},{"text":"Oxígeno","correct":true}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane',1002,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000013','c2449f10-323d-4ba2-b438-fdc1f452dbf3','Una sustancia cruza mediante una proteína a favor de su gradiente, sin gasto directo de ATP. ¿Qué mecanismo describe?','La participación de una proteína no convierte por sí sola el transporte en activo.','[{"text":"Fagocitosis","correct":false},{"text":"Síntesis proteica","correct":false},{"text":"Difusión facilitada","correct":true},{"text":"Transporte activo primario","correct":false}]'::jsonb,2,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane',1003,'clinical_case','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000014','c2449f10-323d-4ba2-b438-fdc1f452dbf3','¿Qué se desplaza en la ósmosis?','La ósmosis es el movimiento neto de agua a través de una membrana selectivamente permeable.','[{"text":"Cromosomas","correct":false},{"text":"Agua","correct":true},{"text":"Solo proteínas","correct":false},{"text":"Solo iones sodio","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane',1004,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000015','c2449f10-323d-4ba2-b438-fdc1f452dbf3','¿Qué caracteriza al transporte activo primario?','En el transporte activo primario, el transportador utiliza ATP directamente.','[{"text":"El uso directo de ATP por la proteína transportadora","correct":true},{"text":"La ausencia total de aporte energético","correct":false},{"text":"El paso exclusivo por la bicapa sin proteínas","correct":false},{"text":"El movimiento obligatorio de agua","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane',1005,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000016','c2449f10-323d-4ba2-b438-fdc1f452dbf3','¿Qué significa gradiente de concentración?','Un gradiente expresa una diferencia de concentración que puede impulsar transporte pasivo.','[{"text":"Una capa de fosfolípidos","correct":false},{"text":"Una clase de receptor","correct":false},{"text":"Un tipo de tejido","correct":false},{"text":"Una diferencia de concentración entre dos zonas","correct":true}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane',1006,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000017','c2449f10-323d-4ba2-b438-fdc1f452dbf3','¿Cuál de estas afirmaciones sobre difusión facilitada es correcta?','La difusión facilitada es un mecanismo pasivo mediado por proteínas.','[{"text":"Ocurre sin ninguna proteína","correct":false},{"text":"Mueve obligatoriamente sustancias contra su gradiente","correct":false},{"text":"Utiliza proteínas sin requerir ATP directamente para impulsar el paso","correct":true},{"text":"Siempre consume ATP en el transportador","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane',1007,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000018','c2449f10-323d-4ba2-b438-fdc1f452dbf3','Dos compartimentos contienen distintas concentraciones de un soluto impermeante. Si solo el agua puede cruzar, ¿hacia qué lado se moverá netamente, en condiciones comparables?','La diferencia de solutos no permeantes genera movimiento osmótico neto de agua hacia el medio más concentrado.','[{"text":"No puede moverse en ninguna dirección","correct":false},{"text":"Hacia el lado con mayor concentración de ese soluto","correct":true},{"text":"Hacia el lado con menor concentración de ese soluto","correct":false},{"text":"Siempre hacia la izquierda","correct":false}]'::jsonb,2,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane',1008,'clinical_case','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000019','c2449f10-323d-4ba2-b438-fdc1f452dbf3','¿Qué componente contribuye a modular la fluidez de la membrana plasmática?','El colesterol es un componente de la membrana que contribuye a sus propiedades de fluidez.','[{"text":"Colesterol","correct":true},{"text":"Colágeno extracelular únicamente","correct":false},{"text":"Hemoglobina circulante","correct":false},{"text":"ADN nuclear","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane',1009,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000020','c2449f10-323d-4ba2-b438-fdc1f452dbf3','¿Qué fuente impulsa inmediatamente un transporte activo secundario acoplado?','El transporte secundario aprovecha otro gradiente; su mantenimiento depende indirectamente de mecanismos que utilizan energía.','[{"text":"La contracción de una serosa","correct":false},{"text":"La desaparición de todas las proteínas","correct":false},{"text":"El ATP consumido directamente por cada cotransportador","correct":false},{"text":"El gradiente de otra sustancia","correct":true}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane',1010,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
UPDATE public.curriculum_lessons SET title='Fundamentos: razonamiento, intervención y responsabilidad profesional',summary='Relaciona valoración, diagnóstico funcional, plan de intervención y reevaluación desde un enfoque biopsicosocial.',content='### Objetivos de repaso
Comprender el proceso de atención en fisioterapia, justificar una intervención y reconocer los factores personales y del entorno. Este repaso desarrolla competencias del programa; no sustituye los bloques de historia y técnicas de la asignatura.

### Un proceso de atención razonado
La historia clínica organiza información sobre el motivo de consulta, la evolución y las dificultades que experimenta la persona. La entrevista y la exploración aportan información que se analiza conjuntamente. El diagnóstico de fisioterapia se fundamenta en la valoración y el razonamiento clínico, e identifica problemas relevantes para el funcionamiento.

### Del diagnóstico al plan
La intervención se construye considerando la valoración, la evidencia científica disponible, las aportaciones de otros profesionales y la participación del paciente. Los objetivos deben responder a las necesidades de esa persona. Aplicar una técnica sin relacionarla con un problema identificado impide justificar su elección y valorar su utilidad.

### Funcionamiento y contexto
La recuperación no depende solamente de una estructura corporal. Los factores psicosociales y ambientales también pueden influir. Una barrera arquitectónica puede dificultar que una persona participe en una actividad aunque su capacidad física mejore. El enfoque biopsicosocial obliga a recoger información sobre la persona y su entorno, sin atribuir automáticamente sus dificultades a una única causa.

### Reevaluación y equipo
El plan requiere seguimiento. Comparar los resultados con la valoración inicial y dialogar con el paciente permite reajustarlo. Trabajar de forma interdisciplinar exige coordinar información relevante y reconocer las competencias de cada profesional. Si la situación supera las propias competencias, se solicita ayuda adecuada.

### Responsabilidad y comunicación
La conducta profesional incluye respeto por la intimidad, confidencialidad y trato equitativo. El consentimiento informado requiere información comprensible y participación en las decisiones. Una firma aislada no reemplaza la comunicación. El registro debe ser pertinente para la atención y transmitirse por canales adecuados.

### Caso de aplicación
Una persona mejora en una prueba física, pero sigue sin poder acceder a su vivienda por las escaleras. La reevaluación debe considerar esa dificultad concreta y el entorno, además de la prueba. La mejoría de una medida no demuestra por sí sola que se hayan alcanzado todos los objetivos.

### Autoevaluación
Explica cómo se conectan valoración, diagnóstico, objetivos, intervención y reevaluación. Propón un factor del entorno que pueda modificar el plan.

Ejercicios originales de entrenamiento; no son preguntas de examen autenticadas.',key_points='["La valoración fundamenta el diagnóstico de fisioterapia.","El plan integra evidencia, persona, entorno y equipo.","Los factores psicosociales y ambientales pueden influir en la recuperación.","La reevaluación orienta ajustes del plan.","Intimidad, confidencialidad y comunicación forman parte de la práctica."]'::jsonb,source_files='[{"url":"https://www.uvic.cat/es/assignatura/4412","label":"UVic-UCC · Plan docente · alcance de la asignatura","verified_at":"2026-10-30"}]'::jsonb,updated_at=now() WHERE id='ab7d1b48-00b2-45f3-97ae-c055c7a6a0e0' AND (content='La fisioterapia es una profesión sanitaria con responsabilidades clínicas, éticas y de comunicación. El acto fisioterapéutico comprende la valoración, la toma de decisiones y la intervención dentro del ámbito profesional.\n\nLa deontología reúne principios que orientan la conducta profesional. El consentimiento informado implica que la persona recibe información comprensible y participa en las decisiones relacionadas con su atención.\n\nEn la práctica, el fisioterapeuta debe reconocer los límites de su actuación, respetar la autonomía de la persona y adaptar su comunicación al contexto asistencial.

### Aplicación práctica
En una situación de atención, la conducta profesional combina competencia técnica, comunicación comprensible y respeto por la decisión de la persona. Antes de intervenir, conviene explicar qué se propone, comprobar que la información se ha entendido y adaptar el lenguaje al contexto. Si la situación supera el ámbito de actuación o requiere otra competencia, reconocer ese límite forma parte de una práctica segura. Así, valoración, decisión, consentimiento y comunicación no son elementos separados: forman parte del mismo acto fisioterapéutico.' OR content='### Objetivos de repaso
Comprender el proceso de atención en fisioterapia, justificar una intervención y reconocer los factores personales y del entorno. Este repaso desarrolla competencias del programa; no sustituye los bloques de historia y técnicas de la asignatura.

### Un proceso de atención razonado
