Ejercicios originales de entrenamiento; no son preguntas de examen autenticadas.');
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000021','276218a0-f41a-4e03-b152-024f9eea80fb','¿Qué secuencia expresa mejor el razonamiento del proceso de atención?','La valoración y el análisis de información relevante fundamentan el diagnóstico y el plan.','[{"text":"Recoger información, valorar, formular el diagnóstico y planificar la intervención","correct":true},{"text":"Elegir una técnica y omitir la valoración","correct":false},{"text":"Tratar primero y registrar solo si fracasa","correct":false},{"text":"Decidir el alta sin conocer la situación inicial","correct":false}]'::jsonb,1,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4412',1001,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4412"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000022','276218a0-f41a-4e03-b152-024f9eea80fb','¿Qué papel tiene la evidencia científica disponible al diseñar el plan?','El programa integra evidencia, diagnóstico, aportaciones profesionales y participación del usuario.','[{"text":"Sustituye toda información del paciente","correct":false},{"text":"Se usa solo después del alta","correct":false},{"text":"Permite ignorar los aspectos de seguridad","correct":false},{"text":"Se integra con la valoración y la participación del paciente","correct":true}]'::jsonb,1,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4412',1002,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4412"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000023','276218a0-f41a-4e03-b152-024f9eea80fb','Una medida física mejora, pero la persona no logra una tarea prioritaria. ¿Qué procede?','La evaluación del plan y el diálogo con el paciente permiten ajustar la intervención a sus necesidades.','[{"text":"Ignorar la dificultad referida","correct":false},{"text":"Repetir el mismo plan sin revisar resultados","correct":false},{"text":"Reevaluar la tarea, el contexto y los objetivos con la persona","correct":true},{"text":"Dar por alcanzados todos los objetivos","correct":false}]'::jsonb,2,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4412',1003,'clinical_case','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4412"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000024','276218a0-f41a-4e03-b152-024f9eea80fb','¿Qué ejemplo describe una barrera arquitectónica relevante para la recuperación funcional?','Las barreras arquitectónicas son elementos del entorno que pueden dificultar la actividad y la participación.','[{"text":"La fecha de impresión de un manual","correct":false},{"text":"Una entrada con escaleras que la persona no puede utilizar","correct":true},{"text":"Una preferencia musical","correct":false},{"text":"El nombre comercial de una técnica","correct":false}]'::jsonb,1,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4412',1004,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4412"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000025','276218a0-f41a-4e03-b152-024f9eea80fb','¿Qué conducta expresa trabajo interdisciplinar?','La colaboración interdisciplinar implica coordinación y uso de canales de comunicación adecuados.','[{"text":"Coordinar la atención con otros profesionales según las necesidades","correct":true},{"text":"Duplicar intervenciones sin comunicarlo","correct":false},{"text":"Suponer que una profesión resuelve todos los problemas","correct":false},{"text":"Compartir información clínica en cualquier canal público","correct":false}]'::jsonb,1,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4412',1005,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4412"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000026','276218a0-f41a-4e03-b152-024f9eea80fb','¿Qué información complementa los datos físicos desde un enfoque biopsicosocial?','Los factores psicosociales y del entorno pueden influir en la recuperación y deben considerarse.','[{"text":"Solo la marca del material disponible","correct":false},{"text":"Solo la fecha de nacimiento","correct":false},{"text":"Solo el diagnóstico de otra persona","correct":false},{"text":"Factores psicosociales y ambientales relevantes","correct":true}]'::jsonb,1,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4412',1006,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4412"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000027','276218a0-f41a-4e03-b152-024f9eea80fb','¿Qué pregunta favorece la participación del paciente al definir el plan?','Preguntar por necesidades y actividades facilita construir un plan con participación de la persona.','[{"text":"¿Podemos omitir sus preferencias?","correct":false},{"text":"¿Está de acuerdo en no conocer los objetivos?","correct":false},{"text":"¿Qué actividad le gustaría recuperar y qué dificultades encuentra?","correct":true},{"text":"¿Acepta todo sin preguntas?","correct":false}]'::jsonb,2,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4412',1007,'clinical_case','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4412"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000028','276218a0-f41a-4e03-b152-024f9eea80fb','¿Para qué sirve comparar los resultados con la valoración inicial?','La reevaluación crítica permite revisar los efectos de la intervención y realizar ajustes.','[{"text":"Para reemplazar la confidencialidad","correct":false},{"text":"Para evaluar la evolución y reajustar el plan si hace falta","correct":true},{"text":"Para evitar cualquier diálogo","correct":false},{"text":"Para justificar siempre la misma técnica","correct":false}]'::jsonb,1,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4412',1008,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4412"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000029','276218a0-f41a-4e03-b152-024f9eea80fb','¿Qué práctica protege la intimidad y la confidencialidad?','La comunicación profesional debe respetar la intimidad y el secreto profesional.','[{"text":"Comunicar información pertinente por un canal asistencial adecuado","correct":true},{"text":"Comentar datos identificativos en una sala pública","correct":false},{"text":"Publicar historias clínicas sin protección","correct":false},{"text":"Reenviar todo el expediente a cualquier conocido","correct":false}]'::jsonb,1,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4412',1009,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4412"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000030','276218a0-f41a-4e03-b152-024f9eea80fb','¿Qué elemento permite justificar la elección de una intervención?','El plan se construye a partir de la valoración y el diagnóstico; debe poder evaluarse en relación con las necesidades de la persona.','[{"text":"Que sea la única técnica que se conoce","correct":false},{"text":"Que se aplique igual a todos","correct":false},{"text":"Que evite medir resultados","correct":false},{"text":"Su relación con un problema identificado y los objetivos acordados","correct":true}]'::jsonb,1,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4412',1010,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4412"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_topics (id,unit_id,name,slug,description,display_order,content_language,translation_mode,is_active) VALUES ('b7301030-2026-4000-8001-000000000001','b7301030-2026-4000-8000-000000000001','Psicología: aprendizaje y relación terapéutica','s1-psych-20261030','Diferencia condicionamiento clásico y operante y aplica sus conceptos sin confundir refuerzo con castigo.',1,'es','none',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_lessons (id,topic_id,title,summary,content,key_points,source_files,display_order,validation_status,is_published) VALUES ('b7301030-2026-4000-8002-000000000001','b7301030-2026-4000-8001-000000000001','Psicología: aprendizaje y relación terapéutica','Diferencia condicionamiento clásico y operante y aplica sus conceptos sin confundir refuerzo con castigo.','### Objetivos de repaso
Distinguir aprendizaje por asociación de estímulos y aprendizaje por consecuencias; utilizar correctamente refuerzo positivo, refuerzo negativo y castigo. Este bloque complementa los modelos y la comunicación del programa de Psicología.

### Dos formas de aprendizaje
En el condicionamiento clásico se aprende una relación entre estímulos. Un estímulo inicialmente neutro, después de asociarse con otro que provoca una respuesta, puede terminar desencadenando una respuesta aprendida.
En el condicionamiento operante se relaciona una conducta con sus consecuencias: estas pueden aumentar o disminuir su probabilidad futura.

### Vocabulario del condicionamiento clásico
El estímulo incondicionado desencadena una respuesta sin aprendizaje previo. La respuesta incondicionada es esa reacción no aprendida. El estímulo condicionado adquiere su efecto mediante la asociación; la respuesta condicionada es la respuesta aprendida.
No confundas estímulo, que se presenta, con respuesta, que hace el organismo. Una reacción anticipatoria aprendida no demuestra por sí sola una nueva lesión.

### Refuerzo y castigo
Refuerzo significa que aumenta la probabilidad de una conducta. Castigo significa que disminuye. Positivo indica que se añade un estímulo; negativo, que se retira. Estas palabras no equivalen a bueno y malo.
Refuerzo positivo: se añade una consecuencia y la conducta aumenta. Refuerzo negativo: se retira una consecuencia aversiva y la conducta aumenta. Castigo negativo: se retira una consecuencia agradable y la conducta disminuye. Por tanto, refuerzo negativo y castigo no son sinónimos.

### Moldeamiento
Consiste en reforzar aproximaciones sucesivas a la conducta objetivo. En lugar de exigir desde el principio una ejecución completa, se reconocen pasos cada vez más cercanos al objetivo. Es un concepto de aprendizaje, no una prescripción automática de ejercicio para cualquier paciente.

### Relación terapéutica
El programa incluye comunicación, obstáculos comunicativos y adherencia. Comprender el comportamiento ayuda a formular preguntas sobre dificultades reales y adaptar la explicación. Se mantiene el respeto por la persona y sus decisiones; conocer un mecanismo de aprendizaje no autoriza a manipularla.

### Aplicación
Si un reconocimiento verbal tras una práctica se acompaña de un aumento de esa conducta, encaja con refuerzo positivo. Para clasificar el mecanismo hay que comprobar qué se añade o retira y cómo cambia la conducta; la intención del profesional no basta.

### Autoevaluación
Construye una tabla de dos criterios: añadir o retirar, aumentar o disminuir. Explica por qué retirar un estímulo no significa siempre castigar.

Material de entrenamiento original, no examen oficial.','["Clásico: asociación entre estímulos.","Operante: conducta y consecuencias.","Refuerzo aumenta; castigo disminuye.","Positivo añade; negativo retira.","Moldeamiento: aproximaciones sucesivas."]'::jsonb,'[{"url":"https://www.uvic.cat/es/assignatura/4409","label":"UVic-UCC · Plan docente · alcance de la asignatura","verified_at":"2026-10-30"},{"url":"https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning","label":"OpenStax · Texto académico abierto · fundamento del repaso","verified_at":"2026-10-30"},{"url":"https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning","label":"OpenStax · Texto académico abierto · fundamento del repaso","verified_at":"2026-10-30"}]'::jsonb,1,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000031','b7301030-2026-4000-8001-000000000001','¿Qué relación se aprende principalmente en el condicionamiento clásico?','El condicionamiento clásico asocia estímulos y permite anticipar acontecimientos.','[{"text":"Una asociación entre estímulos","correct":true},{"text":"La estructura de una articulación","correct":false},{"text":"El efecto exclusivo de una consecuencia tras una conducta","correct":false},{"text":"La composición de una membrana","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning',1,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000032','b7301030-2026-4000-8001-000000000001','¿Qué caracteriza al condicionamiento operante?','Las consecuencias pueden aumentar o disminuir la probabilidad de repetir la conducta.','[{"text":"La asociación exclusiva entre dos estímulos sin atender a conductas","correct":false},{"text":"La ausencia de aprendizaje","correct":false},{"text":"La clasificación de tejidos","correct":false},{"text":"La asociación entre una conducta y sus consecuencias","correct":true}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning',2,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000033','b7301030-2026-4000-8001-000000000001','En condicionamiento operante, ¿qué significa refuerzo?','Refuerzo se define por el aumento de la conducta, tanto si es positivo como negativo.','[{"text":"Añadir siempre un estímulo desagradable","correct":false},{"text":"Retirar siempre un premio","correct":false},{"text":"Aumento de la probabilidad de una conducta","correct":true},{"text":"Disminución obligatoria de la conducta","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning',3,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000034','b7301030-2026-4000-8001-000000000001','¿Qué significa negativo en refuerzo negativo?','Negativo indica retirada; refuerzo indica aumento de la conducta.','[{"text":"Que el aprendizaje es imposible","correct":false},{"text":"Que se retira un estímulo","correct":true},{"text":"Que la conducta siempre disminuye","correct":false},{"text":"Que se aplica necesariamente un castigo","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning',4,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000035','b7301030-2026-4000-8001-000000000001','Después de una conducta se añade una consecuencia agradable y la conducta aumenta. ¿Cómo se clasifica?','Se añade un estímulo y aumenta la conducta: son los dos criterios del refuerzo positivo.','[{"text":"Refuerzo positivo","correct":true},{"text":"Castigo positivo","correct":false},{"text":"Castigo negativo","correct":false},{"text":"Estímulo incondicionado","correct":false}]'::jsonb,2,'Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning',5,'clinical_case','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000036','b7301030-2026-4000-8001-000000000001','Se retira una consecuencia aversiva tras una conducta y esta aumenta. ¿Qué mecanismo es?','Retirar un estímulo aversivo aumentando la conducta corresponde a refuerzo negativo.','[{"text":"Castigo negativo","correct":false},{"text":"Castigo positivo","correct":false},{"text":"Ausencia de aprendizaje","correct":false},{"text":"Refuerzo negativo","correct":true}]'::jsonb,2,'Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning',6,'clinical_case','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000037','b7301030-2026-4000-8001-000000000001','Se retira una consecuencia agradable y la conducta disminuye. ¿Qué concepto corresponde?','En esta clasificación, retirar es negativo y disminuir una conducta es castigo.','[{"text":"Refuerzo positivo","correct":false},{"text":"Condicionamiento clásico necesariamente","correct":false},{"text":"Castigo negativo","correct":true},{"text":"Refuerzo negativo","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning',7,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000038','b7301030-2026-4000-8001-000000000001','¿Qué describe el moldeamiento?','El moldeamiento refuerza progresivamente respuestas cada vez más cercanas al objetivo.','[{"text":"Confundir estímulos con respuestas","correct":false},{"text":"Reforzar aproximaciones sucesivas a una conducta objetivo","correct":true},{"text":"Exigir solo el resultado final desde el primer intento","correct":false},{"text":"Aplicar siempre un castigo físico","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning',8,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000039','b7301030-2026-4000-8001-000000000001','¿Qué distingue una respuesta condicionada de una respuesta incondicionada?','La respuesta condicionada es aprendida; la incondicionada no necesita ese aprendizaje previo.','[{"text":"La respuesta condicionada se adquiere mediante aprendizaje asociativo","correct":true},{"text":"La respuesta condicionada nunca depende del aprendizaje","correct":false},{"text":"Ambas palabras significan un estímulo externo","correct":false},{"text":"La respuesta incondicionada exige siempre entrenamiento","correct":false}]'::jsonb,1,'Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning',9,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000040','b7301030-2026-4000-8001-000000000001','Un profesional añade una felicitación, pero la conducta no aumenta. ¿Qué puede concluirse con esos datos?','El refuerzo se identifica por su efecto sobre la conducta, no solo por la intención de quien lo ofrece.','[{"text":"Toda felicitación es necesariamente un refuerzo eficaz","correct":false},{"text":"Se ha probado un castigo negativo","correct":false},{"text":"Se ha demostrado una lesión","correct":false},{"text":"No se ha demostrado que la felicitación funcione como refuerzo","correct":true}]'::jsonb,2,'Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning',10,'clinical_case','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_topics (id,unit_id,name,slug,description,display_order,content_language,translation_mode,is_active) VALUES ('b7301030-2026-4000-8001-000000000002','b7301030-2026-4000-8000-000000000002','Cultura, Sociedad y Salud: determinantes, diversidad y equidad','s1-culture-20261030','Analiza barreras sociales y culturales sin reducir los problemas de salud a decisiones individuales.',1,'es','none',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_lessons (id,topic_id,title,summary,content,key_points,source_files,display_order,validation_status,is_published) VALUES ('b7301030-2026-4000-8002-000000000002','b7301030-2026-4000-8001-000000000002','Cultura, Sociedad y Salud: determinantes, diversidad y equidad','Analiza barreras sociales y culturales sin reducir los problemas de salud a decisiones individuales.','### Objetivos de repaso
Reconocer determinantes sociales de la salud, analizar barreras de acceso y comprender la diversidad sin convertirla en estereotipos. Este bloque desarrolla contenidos de desigualdad y comunicación intercultural.

### Salud y condiciones de vida
Los determinantes sociales son las condiciones en que las personas nacen, crecen, viven, trabajan y envejecen, junto con las fuerzas sociales, políticas y económicas que las configuran. Incluyen vivienda, educación, alimentación, trabajo y protección social. La atención sanitaria importa, pero no agota las causas de la salud.

### Gradiente social
Las diferencias de salud no se limitan a una separación entre pobreza extrema y el resto de la población. El gradiente social describe una relación progresiva entre desventaja social y peores resultados de salud. Es una relación poblacional; no permite predecir con certeza la salud de cada individuo.

### Desigualdad y equidad
Describir una diferencia es un primer paso. Analizar la equidad exige preguntarse por la distribución de recursos, oportunidades y barreras. Ofrecer exactamente el mismo recurso puede dejar sin acceso a quienes encuentran obstáculos distintos. Mejorar el acceso puede requerir respuestas adaptadas al contexto.

### Diversidad y comunicación
La antropología de la salud estudia las creencias y prácticas relacionadas con salud, enfermedad y cuidados dentro de su contexto. Una nacionalidad no determina por sí sola lo que cree una persona. Conviene explorar cómo entiende su problema, qué espera de la atención y qué dificultades comunicativas existen, con respeto y sin suposiciones.

### Género, estigma y discriminación
El programa incluye estas dimensiones porque pueden influir en experiencias y oportunidades. Un análisis respetuoso evita culpar a un colectivo y examina barreras y relaciones sociales. La participación de la persona en la atención ayuda a comprender su situación concreta.

### Aplicación en fisioterapia
Una persona no acude porque sus turnos laborales y el transporte dificultan la asistencia. Antes de atribuirlo a falta de interés, se exploran esas barreras y las opciones de coordinación. Una vivienda inadecuada o la dificultad para costear desplazamientos también pueden condicionar el seguimiento.

### Autoevaluación
Separa en un caso lo observado de lo supuesto. Identifica una barrera social, una pregunta para comprenderla y una posible adaptación que deba discutirse con la persona y el equipo.

Material original de entrenamiento basado en UVic y OMS; no es un examen oficial.','["Los determinantes sociales van más allá de la atención sanitaria.","El gradiente social es progresivo y poblacional.","Las barreras de acceso pueden exigir respuestas adaptadas.","La diversidad no permite presuponer creencias individuales.","Explorar barreras antes de atribuir falta de interés."]'::jsonb,'[{"url":"https://www.uvic.cat/es/assignatura/4410","label":"UVic-UCC · Plan docente · alcance de la asignatura","verified_at":"2026-10-30"},{"url":"https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health","label":"OMS · Determinantes sociales de la salud","verified_at":"2026-10-30"}]'::jsonb,1,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000041','b7301030-2026-4000-8001-000000000002','¿Cuál es un determinante social de la salud?','La vivienda forma parte de las condiciones de vida que influyen en la salud.','[{"text":"Las condiciones de vivienda","correct":true},{"text":"La secuencia de una proteína aislada","correct":false},{"text":"El diámetro de una mitocondria","correct":false},{"text":"La forma de una válvula cardíaca","correct":false}]'::jsonb,1,'Entrenamiento original · https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health',1,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000042','b7301030-2026-4000-8001-000000000002','¿Qué expresa el gradiente social de la salud?','La OMS describe una relación entre desventaja, ingresos, educación y salud a lo largo de la escala social.','[{"text":"Que solo existe diferencia entre dos grupos extremos","correct":false},{"text":"Que la salud depende exclusivamente de la genética","correct":false},{"text":"Que todas las personas tienen idénticas condiciones","correct":false},{"text":"Una relación progresiva entre desventaja social y peores resultados de salud","correct":true}]'::jsonb,1,'Entrenamiento original · https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health',2,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000043','b7301030-2026-4000-8001-000000000002','Una persona falta a sesiones por turnos laborales y falta de transporte. ¿Qué interpretación está mejor fundamentada?','El trabajo y las condiciones de acceso pueden limitar la asistencia; no debe inferirse desinterés sin explorarlos.','[{"text":"La nacionalidad explica toda la conducta","correct":false},{"text":"La fisiología celular deja de ser relevante","correct":false},{"text":"Existen barreras sociales de acceso que deben explorarse","correct":true},{"text":"Se demuestra que no quiere recuperarse","correct":false}]'::jsonb,2,'Entrenamiento original · https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health',3,'clinical_case','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000044','b7301030-2026-4000-8001-000000000002','¿Qué estudia la antropología de la salud?','El programa aborda las creencias, prácticas e instituciones vinculadas al proceso salud-enfermedad-atención.','[{"text":"Solo los resultados de una radiografía","correct":false},{"text":"Representaciones y prácticas de salud, enfermedad y cuidados en su contexto","correct":true},{"text":"Solo la forma de los huesos","correct":false},{"text":"Solo las reacciones químicas celulares","correct":false}]'::jsonb,1,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4410',4,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4410"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000045','b7301030-2026-4000-8001-000000000002','¿Qué pregunta favorece una comunicación intercultural respetuosa?','Explorar el significado y las expectativas de la persona evita imponer supuestos sobre su cultura.','[{"text":"¿Cómo entiende su problema y qué espera de la atención?","correct":true},{"text":"Por su origen, usted debe pensar lo mismo que todos","correct":false},{"text":"¿Podemos ignorar sus dudas?","correct":false},{"text":"¿Acepta que no le expliquemos el plan?","correct":false}]'::jsonb,2,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4410',5,'clinical_case','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4410"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000046','b7301030-2026-4000-8001-000000000002','¿Qué afirmación distingue una relación poblacional de una predicción individual?','Un patrón de desigualdad poblacional no es un destino individual ni una prueba diagnóstica.','[{"text":"Todas las personas con el mismo ingreso enferman igual","correct":false},{"text":"La educación determina cada diagnóstico con certeza","correct":false},{"text":"La vivienda nunca influye en la salud","correct":false},{"text":"El gradiente social no determina con certeza la salud de cada persona","correct":true}]'::jsonb,1,'Entrenamiento original · https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health',6,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000047','b7301030-2026-4000-8001-000000000002','¿Qué grupo de factores incluye condiciones sociales relevantes para la salud?','La OMS incluye educación, condiciones laborales y protección social entre los determinantes.','[{"text":"Solo frecuencia cardíaca y temperatura","correct":false},{"text":"Solo tipo de tejido y membrana","correct":false},{"text":"Educación, empleo y protección social","correct":true},{"text":"Solo grupo sanguíneo y ADN","correct":false}]'::jsonb,1,'Entrenamiento original · https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health',7,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000048','b7301030-2026-4000-8001-000000000002','Dos personas reciben el mismo horario, pero una no puede acceder por su empleo. ¿Qué análisis favorece la equidad?','La igualdad formal del recurso no elimina diferencias de acceso derivadas de las condiciones de vida.','[{"text":"Atribuirlo automáticamente a una creencia cultural","correct":false},{"text":"Examinar la barrera y valorar opciones de acceso adaptadas","correct":true},{"text":"Suponer que el mismo horario garantiza el mismo acceso","correct":false},{"text":"Excluirla sin explorar alternativas","correct":false}]'::jsonb,2,'Entrenamiento original · https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health',8,'clinical_case','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000049','b7301030-2026-4000-8001-000000000002','¿Por qué no basta con mejorar únicamente los servicios clínicos para abordar los determinantes sociales?','La salud depende también de condiciones no médicas y de la distribución de recursos y oportunidades.','[{"text":"Porque vivienda, educación y condiciones laborales también influyen en la salud","correct":true},{"text":"Porque la atención sanitaria carece de utilidad","correct":false},{"text":"Porque los determinantes sociales son exclusivamente genéticos","correct":false},{"text":"Porque todas las barreras se resuelven con una prueba física","correct":false}]'::jsonb,1,'Entrenamiento original · https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health',9,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.curriculum_quiz_questions (id,topic_id,question_text,explanation,options,difficulty,source_label,display_order,question_type,metadata,validation_status,is_published) VALUES ('b7301030-2026-4000-8003-000000000050','b7301030-2026-4000-8001-000000000002','¿Qué conducta evita un estereotipo cultural durante la entrevista?','La comprensión sociocultural requiere contextualizar la experiencia individual y evitar generalizaciones automáticas.','[{"text":"Asignarle creencias por su apellido","correct":false},{"text":"Suponer que su grupo es homogéneo","correct":false},{"text":"Interpretar el silencio siempre del mismo modo","correct":false},{"text":"Preguntar por la experiencia de esa persona sin deducirla de su origen","correct":true}]'::jsonb,1,'Entrenamiento original · https://www.uvic.cat/es/assignatura/4410',10,'mcq','{"content_batch":"es-s1-20261030","academic_semester":1,"academic_year":1,"language":"es","origin":"original_training","external_expert_review":"pending","source_urls":["https://www.uvic.cat/es/assignatura/4410"],"verified_at":"2026-10-30"}'::jsonb,'source_validated',true) ON CONFLICT (id) DO NOTHING;
