IF EXISTS (SELECT 1 FROM public.curriculum_quiz_questions q JOIN public.curriculum_topics t ON t.id=q.topic_id JOIN public.curriculum_units u ON u.id=t.unit_id WHERE q.metadata->>'content_batch'='es-s1-20261030' AND (u.program_id<>'kineo-es' OR u.academic_level_id<>'83040b48-7a19-46d7-a61c-5a3d2d947fb6')) THEN RAISE EXCEPTION 'Wrong program scope'; END IF;
